/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var BaseDataSet = require( '@stdlib/plot/vega/data/base/ctor' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getValues = require( './values/get.js' );
var setValues = require( './values/set.js' );


// VARIABLES //

var debug = logger( 'vega:values-data:main' );


// MAIN //

/**
* Data set constructor for inline values.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - data set name
* @param {boolean} [options.async=false] - boolean indicating whether data loading or reformatting should be performed asynchronously
* @param {Format} [options.format] - format specification for parsing a data file or values
* @param {Array<Transform>} [options.transforms=[]] - list of transforms to perform on input data
* @param {Array<Trigger>} [options.triggers=[]] - list of updates to perform when trigger conditions are met
* @param {*} [options.values] - inline data set values
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {DataSet} data set instance
*
* @example
* var trigger = new DataSet({
*     'name': 'table'
* });
* // returns <DataSet>
*/
function DataSet( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof DataSet ) ) {
		return new DataSet( options );
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the data set name.' );
	}
	BaseDataSet.call( this, {
		'name': options.name
	});

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `BaseDataSet` prototype.
*/
inherit( DataSet, BaseDataSet );

/**
* Constructor name.
*
* @private
* @name name
* @memberof DataSet
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( DataSet, 'name', 'DataSet' );

/**
* Inline data set values.
*
* @name values
* @memberof DataSet.prototype
* @type {*}
*
* @example
* var data = new DataSet({
*     'name': 'table',
*     'values': [ 1, 2, 3 ]
* });
*
* var v = data.values;
* // returns [ 1, 2, 3 ]
*/
setReadWriteAccessor( DataSet.prototype, 'values', getValues, setValues );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof DataSet.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var data = new DataSet({
*     'name': 'table'
* });
*
* var v = data.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( DataSet.prototype, 'toJSON', function toJSON() {
	var out;

	// Call the parent method so that we serialize all inherited properties:
	out = BaseDataSet.prototype.toJSON.call( this );

	// Explicitly assign the inlined values in order to avoid triggering explicit JSON serialization (note: JSON.stringify will recursively call `#.toJSON`, so values will still be JSON serialized for portable transmission; however, we don't want to eagerly serialize here in order to avoid unnecessary data copying):
	out.values = this._values;

	return out;
});


// EXPORTS //

module.exports = DataSet;
